package com.sunshine.yunji.content.resource.application;
import com.sunshine.yunji.content.shared.*;
import com.sunshine.yunji.content.identity.application.Actors;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;

@Service
public class ResourceService {
 private final Db db;private final Actors actors;
 public ResourceService(Db db,Actors actors){this.db=db;this.actors=actors;}
 public record Subject(long organizationId,String code,String name){}
 public record Dimension(String kind,String code,String name){}
 public record Resource(long organizationId,long subjectId,String title,String type,String status,Long articleId,List<Long> fileIds,int expectedVersion){}
 public record Exam(long organizationId,long subjectId,Instant startsAt,String displayTimezone,String sourceReference){}
 public record Artifact(String name,String platform,String status,Long guideArticleId){}
 public record Release(String versionName,long fileId,String releaseNotes){}
 public record SubjectUpdate(long organizationId,String code,String name,String status,int expectedVersion){}
 public record DimensionUpdate(String kind,String code,String name,String status,int expectedVersion){}
 public record ExamUpdate(long organizationId,long subjectId,Instant startsAt,String displayTimezone,String sourceReference,String status,int expectedVersion){}
 public record ArtifactUpdate(String name,String platform,String status,Long guideArticleId,int expectedVersion){}
 private void manage(){actors.staff().require("yunji:resource:manage");}
 public List<Map<String,Object>> subjects(){return db.rows("SELECT * FROM study_subject WHERE tenant_id='000000' AND status='ENABLED' ORDER BY organization_id,name,id LIMIT 200");}
 public List<Map<String,Object>> dimensions(){return db.rows("SELECT * FROM study_dimension WHERE tenant_id='000000' AND status='ENABLED' ORDER BY kind,code,id LIMIT 200");}
 @Transactional public Map<String,Object> subject(Subject b){manage();db.one("SELECT id FROM organization WHERE id=? AND tenant_id='000000' AND deleted_at IS NULL",b.organizationId);long id=db.id();db.update("INSERT INTO study_subject(id,organization_id,code,name) VALUES(?,?,?,?)",id,b.organizationId,Db.text(b.code,64),Db.text(b.name,150));db.audit(actors.staff().id(),"STAFF","SUBJECT_CREATE","SUBJECT",id,Map.of("code",b.code));return db.one("SELECT * FROM study_subject WHERE id=?",id);}
 @Transactional public Map<String,Object> dimension(Dimension b){manage();BusinessException.require(Set.of("GRADE","MAJOR").contains(b.kind),422,"字典类型错误");long id=db.id();db.update("INSERT INTO study_dimension(id,kind,code,name) VALUES(?,?,?,?)",id,b.kind,Db.text(b.code,64),Db.text(b.name,150));db.audit(actors.staff().id(),"STAFF","DIMENSION_CREATE","DIMENSION",id,Map.of("code",b.code));return db.one("SELECT * FROM study_dimension WHERE id=?",id);}
 public List<Map<String,Object>> adminSubjects(){manage();return db.rows("SELECT * FROM study_subject WHERE tenant_id='000000' ORDER BY organization_id,name,id LIMIT 200");}
 public List<Map<String,Object>> adminDimensions(){manage();return db.rows("SELECT * FROM study_dimension WHERE tenant_id='000000' ORDER BY kind,code,id LIMIT 200");}
 private Map<String,Object> locked(String table,long id,int version){var old=db.one("SELECT * FROM "+table+" WHERE id=? AND tenant_id='000000' FOR UPDATE",id);BusinessException.require(Db.number(old.get("lockVersion"))==version,409,"条目已变化，请重新加载");return old;}
 private void audit(String action,String type,long id){db.audit(actors.staff().id(),"STAFF",action,type,id,Map.of());}
 @Transactional public Map<String,Object> subject(long id,SubjectUpdate b){manage();var old=locked("study_subject",id,b.expectedVersion);BusinessException.require(Set.of("ENABLED","DISABLED").contains(b.status),422,"科目状态错误");db.one("SELECT id FROM organization WHERE id=? AND tenant_id='000000' AND status='ENABLED' AND deleted_at IS NULL",b.organizationId);if(Db.number(old.get("organizationId"))!=b.organizationId)BusinessException.require(db.count("SELECT COUNT(*) FROM resource_package WHERE subject_id=?",id)+db.count("SELECT COUNT(*) FROM exam_schedule WHERE subject_id=?",id)==0,409,"被引用的科目不能移动到其他组织");db.update("UPDATE study_subject SET organization_id=?,code=?,name=?,status=?,lock_version=lock_version+1 WHERE id=?",b.organizationId,Db.text(b.code,64),Db.text(b.name,150),b.status,id);audit("SUBJECT_UPDATE","SUBJECT",id);return db.one("SELECT * FROM study_subject WHERE id=?",id);}
 @Transactional public Map<String,Object> dimension(long id,DimensionUpdate b){manage();locked("study_dimension",id,b.expectedVersion);BusinessException.require(Set.of("GRADE","MAJOR").contains(b.kind)&&Set.of("ENABLED","DISABLED").contains(b.status),422,"字典类型或状态错误");db.update("UPDATE study_dimension SET kind=?,code=?,name=?,status=?,lock_version=lock_version+1 WHERE id=?",b.kind,Db.text(b.code,64),Db.text(b.name,150),b.status,id);audit("DIMENSION_UPDATE","DIMENSION",id);return db.one("SELECT * FROM study_dimension WHERE id=?",id);}
 public List<Map<String,Object>> packages(boolean admin){if(admin)manage();return db.rows("SELECT r.*,s.name subject_name FROM resource_package r JOIN study_subject s ON s.id=r.subject_id WHERE r.tenant_id='000000'"+(admin?"":" AND r.status='PUBLISHED'")+" ORDER BY r.id DESC LIMIT 200");}
 public Map<String,Object> resource(long id,boolean admin){if(admin)manage();var r=db.one("SELECT * FROM resource_package WHERE id=? AND tenant_id='000000'"+(admin?"":" AND status='PUBLISHED'"),id);r.put("files",db.rows("SELECT rf.*,f.sha256,f.size_bytes,f.media_type FROM resource_file rf JOIN file_object f ON f.id=rf.file_id WHERE rf.package_id=? AND rf.version_no=? AND f.status='VERIFIED' ORDER BY rf.sort_order,rf.file_id",id,r.get("currentVersionNo")));return r;}
 @Transactional public Map<String,Object> resource(Long id,Resource b){
  manage();db.one("SELECT id FROM study_subject WHERE id=? AND organization_id=? AND tenant_id='000000' AND status='ENABLED'",b.subjectId,b.organizationId);BusinessException.require(Set.of("TEXTBOOK","REVISION","GENERAL").contains(b.type)&&Set.of("DRAFT","PUBLISHED","OFFLINE").contains(b.status),422,"资源类型或状态错误");if(b.articleId!=null)db.one("SELECT id FROM article WHERE id=? AND tenant_id='000000'",b.articleId);BusinessException.require(b.fileIds!=null&&b.fileIds.size()<=30&&new HashSet<>(b.fileIds).size()==b.fileIds.size(),422,"文件列表错误");
  long key=id==null?db.id():id,version=1;
  if(id==null)db.update("INSERT INTO resource_package(id,organization_id,subject_id,title,resource_type,status,article_id) VALUES(?,?,?,?,?,?,?)",key,b.organizationId,b.subjectId,Db.text(b.title,255),b.type,b.status,b.articleId);
  else{var old=locked("resource_package",key,b.expectedVersion);version=Db.number(old.get("currentVersionNo"))+1;db.update("UPDATE resource_package SET organization_id=?,subject_id=?,title=?,resource_type=?,status=?,article_id=?,current_version_no=?,lock_version=lock_version+1 WHERE id=?",b.organizationId,b.subjectId,Db.text(b.title,255),b.type,b.status,b.articleId,version,key);}
  BusinessException.require(!b.status.equals("PUBLISHED")||!b.fileIds.isEmpty(),422,"发布资料包需要文件");int order=0;
  for(long file:b.fileIds){db.one("SELECT id FROM file_object WHERE id=? AND owner_realm='STAFF' AND status='VERIFIED' AND tenant_id='000000' FOR UPDATE",file);db.update("INSERT INTO resource_file(package_id,file_id,version_no,display_name,sort_order) SELECT ?,id,?,display_name,? FROM file_object WHERE id=?",key,version,order++,file);db.update("INSERT INTO file_reference(file_id,owner_type,owner_id,reference_version_id) VALUES(?,'RESOURCE',?,?)",file,key,version);}
  db.audit(actors.staff().id(),"STAFF","RESOURCE_SAVE","RESOURCE",key,Map.of("version",version));return resource(key,true);
 }
 @Transactional public Map<String,Object> exam(Exam b){manage();db.one("SELECT id FROM study_subject WHERE id=? AND organization_id=? AND tenant_id='000000'",b.subjectId,b.organizationId);try{ZoneId.of(b.displayTimezone);}catch(Exception e){throw new BusinessException(422,"时区无效");}BusinessException.require(b.startsAt!=null,422,"需要考试时间");long id=db.id();db.update("INSERT INTO exam_schedule(id,organization_id,subject_id,starts_at,display_timezone,source_reference) VALUES(?,?,?,?,?,?)",id,b.organizationId,b.subjectId,Timestamp.from(b.startsAt),b.displayTimezone,Db.text(b.sourceReference,500));audit("EXAM_CREATE","EXAM",id);return db.one("SELECT * FROM exam_schedule WHERE id=?",id);}
 public List<Map<String,Object>> exams(){return exams(false);}
 public List<Map<String,Object>> exams(boolean admin){if(admin)manage();return db.rows("SELECT e.*,s.name subject_name,TIMESTAMPDIFF(SECOND,UTC_TIMESTAMP(),e.starts_at) seconds_remaining FROM exam_schedule e JOIN study_subject s ON s.id=e.subject_id WHERE e.tenant_id='000000'"+(admin?"":" AND e.status='PUBLISHED'")+" ORDER BY e.starts_at,e.id LIMIT 200");}
 @Transactional public Map<String,Object> exam(long id,ExamUpdate b){manage();locked("exam_schedule",id,b.expectedVersion);BusinessException.require(Set.of("PUBLISHED","OFFLINE").contains(b.status)&&b.startsAt!=null,422,"时间或状态错误");try{ZoneId.of(b.displayTimezone);}catch(Exception e){throw new BusinessException(422,"时区无效");}db.one("SELECT id FROM study_subject WHERE id=? AND organization_id=? AND tenant_id='000000' AND status='ENABLED'",b.subjectId,b.organizationId);db.update("UPDATE exam_schedule SET organization_id=?,subject_id=?,starts_at=?,display_timezone=?,source_reference=?,status=?,lock_version=lock_version+1 WHERE id=?",b.organizationId,b.subjectId,Timestamp.from(b.startsAt),b.displayTimezone,Db.text(b.sourceReference,500),b.status,id);audit("EXAM_UPDATE","EXAM",id);return db.one("SELECT * FROM exam_schedule WHERE id=?",id);}
 public List<Map<String,Object>> artifacts(boolean admin){if(admin)manage();return db.rows("SELECT * FROM artifact WHERE tenant_id='000000'"+(admin?"":" AND status='PUBLISHED'")+" ORDER BY name,id LIMIT 100");}
 public Map<String,Object> artifact(long id,boolean admin){if(admin)manage();var a=db.one("SELECT * FROM artifact WHERE id=? AND tenant_id='000000'"+(admin?"":" AND status='PUBLISHED'"),id);a.put("versions",db.rows("SELECT * FROM artifact_version WHERE artifact_id=? AND status='PUBLISHED' ORDER BY published_at DESC,id DESC",id));return a;}
 @Transactional public Map<String,Object> artifact(Artifact b){manage();BusinessException.require(Set.of("WINDOWS","MACOS","LINUX","WEB").contains(b.platform)&&Set.of("DRAFT","PUBLISHED","OFFLINE").contains(b.status),422,"插件平台或状态错误");if(b.guideArticleId!=null)db.one("SELECT id FROM article WHERE id=? AND content_type='GUIDE' AND tenant_id='000000'",b.guideArticleId);long id=db.id();db.update("INSERT INTO artifact(id,name,platform,status,guide_article_id) VALUES(?,?,?,?,?)",id,Db.text(b.name,150),b.platform,b.status,b.guideArticleId);audit("ARTIFACT_CREATE","ARTIFACT",id);return artifact(id,true);}
 @Transactional public Map<String,Object> release(long id,Release b){manage();db.one("SELECT id FROM artifact WHERE id=? AND tenant_id='000000' FOR UPDATE",id);var file=db.one("SELECT * FROM file_object WHERE id=? AND owner_realm='STAFF' AND status='VERIFIED' AND media_type='application/zip' AND tenant_id='000000' FOR UPDATE",b.fileId);long version=db.id();db.update("INSERT INTO artifact_version(id,artifact_id,version_name,file_id,sha256,release_notes) VALUES(?,?,?,?,?,?)",version,id,Db.text(b.versionName,64),b.fileId,file.get("sha256"),Db.text(b.releaseNotes,2000));db.update("INSERT INTO file_reference(file_id,owner_type,owner_id,reference_version_id) VALUES(?,'ARTIFACT',?,?)",b.fileId,id,version);db.audit(actors.staff().id(),"STAFF","ARTIFACT_RELEASE","ARTIFACT",id,Map.of("versionId",Long.toString(version),"sha256",file.get("sha256")));return artifact(id,true);}
 @Transactional public Map<String,Object> artifact(long id,ArtifactUpdate b){manage();locked("artifact",id,b.expectedVersion);BusinessException.require(Set.of("WINDOWS","MACOS","LINUX","WEB").contains(b.platform)&&Set.of("DRAFT","PUBLISHED","OFFLINE").contains(b.status),422,"插件平台或状态错误");if(b.guideArticleId!=null)db.one("SELECT id FROM article WHERE id=? AND content_type='GUIDE' AND tenant_id='000000'",b.guideArticleId);db.update("UPDATE artifact SET name=?,platform=?,status=?,guide_article_id=?,lock_version=lock_version+1 WHERE id=?",Db.text(b.name,150),b.platform,b.status,b.guideArticleId,id);audit("ARTIFACT_UPDATE","ARTIFACT",id);return artifact(id,true);}
 @Transactional public void withdraw(String kind,long id,int expectedVersion){manage();String table=switch(kind){case "subjects"->"study_subject";case "dimensions"->"study_dimension";case "packages"->"resource_package";case "exams"->"exam_schedule";case "artifacts"->"artifact";default->throw new BusinessException(422,"资源类型错误");};locked(table,id,expectedVersion);String state=Set.of("subjects","dimensions").contains(kind)?"DISABLED":"OFFLINE";db.update("UPDATE "+table+" SET status=?,lock_version=lock_version+1 WHERE id=?",state,id);audit("RESOURCE_WITHDRAW",kind.toUpperCase(Locale.ROOT),id);}
}
